    public static int rttRect(emon.Port.Bitmap b, int x0, int y0, int x1, int y1, int r, int g, int bl) {
        int y = y0;
        int x = 0;
        while (y < y1) {
            x = x0;
            while (x < x1) {
                emon.Port.bitmapSetU8(b, x, y, 0, r);
                emon.Port.bitmapSetU8(b, x, y, 1, g);
                emon.Port.bitmapSetU8(b, x, y, 2, bl);
                x += 1;
            }
            y += 1;
        }
        return 0;
    }
    public static int rttWord(emon.Port.Cells owords, emon.Port.Cells feats, int x0, int y0, int x1, int y1, int conf, int line) {
        // One OCR word on page 1 with a feature row.
        int f = Evidence.feNew(feats, Evidence.eaOwords(), Evidence.owCount(owords));
        int w = Evidence.owNew(owords, 1, x0, y0, x1, y1, x0, y1, x1, y1, 0, 0, 0, 4, line, conf, f);
        return w;
    }
    public static int rttLine(emon.Port.Cells olines, emon.Port.Cells owords, emon.Port.Cells feats, int y0, int conf) {
        // A line of two words at height y0 (100 centipoints tall); answers its row.
        int first = Evidence.owCount(owords);
        int l = Evidence.olCount(olines);
        rttWord(owords, feats, 100, y0, 600, y0 + 100, conf, l);
        rttWord(owords, feats, 700, y0, 1200, y0 + 100, conf, l);
        Evidence.olNew(olines, 1, 100, y0, 1200, y0 + 100, 100, y0 + 100, 1200, y0 + 100, 0, 0, first, 2);
        Evidence.olSet(olines, l, Evidence.olfPx(), 100);
        Evidence.olSet(olines, l, Evidence.olfPy(), y0);
        Evidence.olSet(olines, l, Evidence.olfPw(), 1100);
        Evidence.olSet(olines, l, Evidence.olfPh(), 100);
        return l;
    }
    public static int rttRun(emon.Port.Cells oruns, emon.Port.Cells olines, emon.Port.Cells owords, int l0, int w0) {
        // A run over the lines [l0, now) and the words [w0, now).
        int r = Evidence.orNew(oruns, 1, 0);
        Evidence.orSet(oruns, r, Evidence.orfLfirst(), l0);
        Evidence.orSet(oruns, r, Evidence.orfLcount(), Evidence.olCount(olines) - l0);
        Evidence.orSet(oruns, r, Evidence.orfWfirst(), w0);
        Evidence.orSet(oruns, r, Evidence.orfWcount(), Evidence.owCount(owords) - w0);
        Evidence.orSet(oruns, r, Evidence.orfOsd(), -1);
        Evidence.orSet(oruns, r, Evidence.orfOconf(), -1);
        return r;
    }
    public static void testTheErasedViewKeepsTheBodyInkAndItsEdgeAndPaintsForeignInkThePaper() {
        emon.Port.Bitmap src = emon.Port.bitmapNew(100, 80, 3);
        emon.Port.Bitmap gray = emon.Port.bitmapNew(100, 80, 1);
        emon.Port.Bitmap bin = emon.Port.bitmapNew(100, 80, 1);
        emon.Port.Bitmap mask = emon.Port.bitmapNew(100, 80, 1);
        emon.Port.Bitmap bodym = emon.Port.bitmapNew(100, 80, 1);
        emon.Port.Bitmap emap = emon.Port.bitmapNew(100, 80, 1);
        emon.Port.Bitmap out = emon.Port.bitmapNew(100, 80, 1);
        emon.Port.Cells views = emon.Port.newCells();
        emon.Port.Cells inks = emon.Port.newCells();
        emon.Port.Cells ws = emon.Port.newCells();
        emon.Port.Cells sv = emon.Port.newCells();
        emon.Port.Cells aux = emon.Port.newCells();
        rttRect(src, 0, 0, 100, 80, 255, 255, 255);
        rttRect(src, 5, 5, 45, 35, 0, 0, 0);
        rttRect(src, 55, 5, 95, 35, 192, 32, 31);
        rttRect(src, 5, 45, 45, 75, 205, 205, 205);
        // a red pixel against the black block's edge: the block's own, as the edge of a glyph is
        rttRect(src, 45, 20, 46, 21, 192, 32, 31);
        Evidence.vwNew(views, 1, Evidence.vkRender(), 2, -1, 100, 80, 15000, 0, -1, 0, 0, 0, 0, 0);
        Norm.nmView(views, inks, 1, 0, src, gray, bin, ws, sv, aux);
        Retarget.rtEraseInto(src, gray, ws, mask, bodym, 130, emap, out);
        emon.Testport.assertEq(emon.Port.bitmapU8(out, 20, 20, 0), 0, "the body's black stays black");
        emon.Testport.assertEq(emon.Port.bitmapU8(out, 70, 20, 0), Norm.nmPaperGray(ws), "a red seal is the paper's");
        emon.Testport.assertEq(emon.Port.bitmapU8(emap, 70, 20, 0), 255, "and the map says it was painted over");
        emon.Testport.assertEq(emon.Port.bitmapU8(out, 20, 60, 0), Norm.nmPaperGray(ws), "a light grey watermark is the paper's");
        emon.Testport.assertEq(emon.Port.bitmapU8(out, 50, 40, 0), emon.Port.bitmapU8(gray, 50, 40, 0), "and the paper stays as it was");
        emon.Testport.assertEq(emon.Port.bitmapU8(emap, 50, 40, 0), 0, "and is not on the map");
        emon.Testport.assertEq(emon.Port.bitmapU8(out, 45, 20, 0), emon.Port.bitmapU8(gray, 45, 20, 0), "foreign ink against the body's ink is kept: it is the body's edge");
        emon.Testport.assertEq(emon.Port.bitmapU8(emap, 45, 20, 0), 0, "and not on the map either");
    }
    public static void testAViewIsAskedByItsHashAndAnotherPixelIsAnotherRequest() {
        emon.Port.BitmapSet bms = emon.Port.newBitmapSet();
        emon.Port.Cells rq = emon.Port.newCells();
        emon.Port.Cells rtp = emon.Port.newCells();
        emon.Port.Cells rq2 = emon.Port.newCells();
        emon.Port.Bitmap v = emon.Port.bmsPut(bms, Plan.puViewId(0, 32), 20, 10, 1);
        Retarget.rtPrep(rtp);
        emon.Port.bitmapSetU8(v, 3, 4, 0, 200);
        Retarget.rtAskView(rq, 300, Plan.puViewId(0, 32), v, 130, emon.Port.newCells(), rtp);
        emon.Testport.assertEq(Plan.recCount(rq), 1, "one request");
        emon.Testport.assertEq(Plan.recKind(rq, 0), Plan.pkOcr(), "an ocr");
        emon.Testport.assertEq(Plan.rqArg(rq, 0, 0), Plan.puViewId(0, 32), "of the kin-made view, by its id from view-base");
        emon.Testport.assertThat(Plan.rqArg(rq, 0, 0) >= Plan.viewBase(), "an id the hosts know for a view");
        emon.Testport.assertEq(Plan.rqArg(rq, 0, 1), 3, "psm 3");
        emon.Testport.assertEq(Plan.rqNargs(rq, 0), 9, "the pixel box, then the two cells of the hash");
        emon.Testport.assertEq(Plan.rqArg(rq, 0, 7), emon.Port.cellsAt(rtp, Retarget.rtpHash()), "the hash's high half is the bulk form's");
        emon.Testport.assertEq(Plan.rqArg(rq, 0, 8), emon.Port.cellsAt(rtp, Retarget.rtpHash() + 1), "and its low half");
        emon.Port.bitmapSetU8(v, 3, 4, 0, 201);
        Retarget.rtAskView(rq2, 300, Plan.puViewId(0, 32), v, 130, emon.Port.newCells(), rtp);
        emon.Testport.assertThat(Plan.rqArg(rq2, 0, 8) != Plan.rqArg(rq, 0, 8), "a view that came out with one other pixel is another request");
    }
    public static void testTheFirstPassCallsForTheLinesItWasUnsureOfAndForTheBodyInkPassOverForeignInk() {
        emon.Port.Cells oruns = emon.Port.newCells();
        emon.Port.Cells olines = emon.Port.newCells();
        emon.Port.Cells owords = emon.Port.newCells();
        emon.Port.Cells feats = emon.Port.newCells();
        emon.Port.Cells rtp = emon.Port.newCells();
        rttLine(olines, owords, feats, 0, 900);
        rttLine(olines, owords, feats, 200, 400);
        rttLine(olines, owords, feats, 400, 950);
        rttLine(olines, owords, feats, 600, 450);
        int run = rttRun(oruns, olines, owords, 0, 0);
        Retarget.rtPrep(rtp);
        emon.Testport.assertEq(Retarget.rtTurns(0, oruns, run, emon.Port.newCells(), 1), 0, "a page with no OSD is upright");
        Evidence.orSet(oruns, run, Evidence.orfOsd(), 90);
        Evidence.orSet(oruns, run, Evidence.orfOconf(), 150);
        emon.Testport.assertEq(Retarget.rtTurns(0, oruns, run, emon.Port.newCells(), 1), 3, "a page OSD is sure is turned 90 degrees (its text runs bottom to top) is made upright by three quarter turns clockwise");
        Evidence.orSet(oruns, run, Evidence.orfOsd(), 180);
        emon.Testport.assertEq(Retarget.rtTurns(0, oruns, run, emon.Port.newCells(), 1), 2, "and one that is upside down by two");
        Evidence.orSet(oruns, run, Evidence.orfOsd(), 90);
        Evidence.orSet(oruns, run, Evidence.orfOconf(), 15);
        emon.Testport.assertEq(Retarget.rtTurns(0, oruns, run, emon.Port.newCells(), 1), 0, "and one it is not sure of, with no text line of the tracer's to say so, is not");
        emon.Testport.assertEq(Retarget.rtTurns(1, oruns, run, emon.Port.newCells(), 1), 0, "and a render is upright, whatever");
        emon.Testport.assertEq(Retarget.rtDecide(0, 0, 2, oruns, run, olines, owords, emon.Port.newCells(), 1, 130, rtp), 2, "two lines under the confidence floor (500): the second (400) and the fourth (450)");
        emon.Testport.assertEq(emon.Port.cellsAt(rtp, Retarget.rtpBody()), 1, "the body-ink pass is wanted: two lines have foreign ink under them");
        emon.Testport.assertEq(emon.Port.cellsAt(rtp, Retarget.rtpQ()), 0, "the page is upright");
        emon.Testport.assertEq(emon.Port.cellsAt(rtp, Retarget.rtpLine0()), 1, "the least sure line first, row 1");
        emon.Testport.assertEq(emon.Port.cellsAt(rtp, Retarget.rtpLine0() + 2), 3, "then row 3");
        Retarget.rtPrep(rtp);
        emon.Testport.assertEq(Retarget.rtDecide(0, 0, 0, oruns, run, olines, owords, emon.Port.newCells(), 1, 130, rtp), 2, "the same lines");
        emon.Testport.assertEq(emon.Port.cellsAt(rtp, Retarget.rtpBody()), 0, "and no body-ink pass: no foreign ink under any line");
        Retarget.rtPrep(rtp);
        emon.Port.cellsSet(rtp, Retarget.rtpErased(), 50);
        Retarget.rtDecide(0, 0, 0, oruns, run, olines, owords, emon.Port.newCells(), 1, 130, rtp);
        emon.Testport.assertEq(emon.Port.cellsAt(rtp, Retarget.rtpBody()), 1, "but one when the view paints over 5 per cent of the page's ink: the text the first pass did not read may lie under it");
        Retarget.rtPrep(rtp);
        emon.Testport.assertEq(Retarget.rtDecide(1, 0, 2, oruns, run, olines, owords, emon.Port.newCells(), 1, 130, rtp), 0, "a born-digital page re-reads no line: its text layer reads it");
        emon.Testport.assertEq(emon.Port.cellsAt(rtp, Retarget.rtpBody()), 1, "but it has its body-ink pass: a witness for arbitration");
        Retarget.rtPrep(rtp);
        Retarget.rtDecide(0, 3, 2, oruns, run, olines, owords, emon.Port.newCells(), 1, 130, rtp);
        emon.Testport.assertEq(emon.Port.cellsAt(rtp, Retarget.rtpQ()), 3, "the turn is the plan's");
        emon.Testport.assertEq(emon.Port.cellsAt(rtp, Retarget.rtpBody()), 0, "and a page that is to be turned has no body-ink pass of the raster as it is");
    }
    public static void testTheBodyInkRunReplacesALineOverForeignInkAndAGhostIsDropped() {
        emon.Port.Cells oruns = emon.Port.newCells();
        emon.Port.Cells olines = emon.Port.newCells();
        emon.Port.Cells owords = emon.Port.newCells();
        emon.Port.Cells feats = emon.Port.newCells();
        emon.Port.Cells rtp = emon.Port.newCells();
        emon.Port.Cells scr = emon.Port.newCells();
        Scan.scPrep(scr);
        rttLine(olines, owords, feats, 0, 900);
        rttLine(olines, owords, feats, 200, 600);
        rttLine(olines, owords, feats, 400, 950);
        rttLine(olines, owords, feats, 800, 400);
        int fr = rttRun(oruns, olines, owords, 0, 0);
        int l1 = Evidence.olCount(olines);
        int w1 = Evidence.owCount(owords);
        // the body-ink run read the second line again and a line that the first pass did not see
        rttLine(olines, owords, feats, 200, 900);
        rttLine(olines, owords, feats, 1000, 800);
        int br = rttRun(oruns, olines, owords, l1, w1);
        Retarget.rtPrep(rtp);
        emon.Port.cellsSet(rtp, Retarget.rtpBrun(), br);
        // what the body-ink view paints over, of each first-pass line's ink (per mille)
        emon.Port.cellsSet(scr, Scan.scShareBase(), 0);
        emon.Port.cellsSet(scr, Scan.scShareBase() + 1, 700);
        emon.Port.cellsSet(scr, Scan.scShareBase() + 2, 50);
        emon.Port.cellsSet(scr, Scan.scShareBase() + 3, 800);
        emon.Testport.assertEq(Retarget.rtLineState(oruns, olines, owords, rtp, scr, 0, 0, br, 0, 4), 0, "a line with no foreign ink under it stays");
        emon.Testport.assertEq(Retarget.rtLineState(oruns, olines, owords, rtp, scr, 1, 1, br, 0, 4), 1, "a line over foreign ink is replaced by the body-ink run's line over it");
        emon.Testport.assertEq(emon.Port.cellsAt(scr, Scan.scPartnerBase() + 1), 4, "that line");
        emon.Testport.assertEq(Retarget.rtLineState(oruns, olines, owords, rtp, scr, 2, 2, br, 0, 4), 0, "a line with a little foreign ink under it stays");
        emon.Testport.assertEq(Retarget.rtLineState(oruns, olines, owords, rtp, scr, 3, 3, br, 0, 4), 2, "a line mostly foreign ink that the body-ink run did not read is a ghost");
        emon.Testport.assertEq(Retarget.rtAdopt(rtp, oruns, fr, olines, owords, scr), 4, "four lines: the first, the second's reading, the third, and the line the first pass did not read; the ghost is dropped");
        emon.Testport.assertEq(emon.Port.cellsAt(scr, Scan.scSelBase()), 0, "the first pass's first line");
        emon.Testport.assertEq(emon.Port.cellsAt(scr, Scan.scSelBase() + 1), 4, "then the body-ink run's line where the second was");
        emon.Testport.assertEq(emon.Port.cellsAt(scr, Scan.scSelBase() + 2), 2, "then the third, in the first pass's order");
        emon.Testport.assertEq(emon.Port.cellsAt(scr, Scan.scSelBase() + 3), 5, "and the body-ink run's line over nothing, below them where it lies");
        emon.Testport.assertEq(emon.Port.cellsAt(rtp, Retarget.rtpPrimary()), fr, "the first pass is the page's reading");
    }
    public static void testALineIsReadAgainByItsCellsOnlyWhenNoTextIsLostAndTheyAreSurer() {
        emon.Port.Cells oruns = emon.Port.newCells();
        emon.Port.Cells olines = emon.Port.newCells();
        emon.Port.Cells owords = emon.Port.newCells();
        emon.Port.Cells feats = emon.Port.newCells();
        emon.Port.Cells rtp = emon.Port.newCells();
        emon.Port.Cells scr = emon.Port.newCells();
        Scan.scPrep(scr);
        rttLine(olines, owords, feats, 0, 600);
        int l1 = Evidence.olCount(olines);
        int w1 = Evidence.owCount(owords);
        int empty = rttRun(oruns, olines, owords, l1, w1);
        Retarget.rtPrep(rtp);
        emon.Port.cellsSet(scr, Scan.scShareBase(), 0);
        emon.Port.cellsSet(rtp, Retarget.rtpNc(), 2);
        // two cells of line 0: the first read as nothing, the second as a line of two words, surer
        emon.Port.cellsSet(rtp, Retarget.rtpCell0() + 4, 0);
        emon.Port.cellsSet(rtp, Retarget.rtpCell0() + 5, empty);
        rttLine(olines, owords, feats, 0, 900);
        int second = rttRun(oruns, olines, owords, l1, w1);
        emon.Port.cellsSet(rtp, Retarget.rtpCell0() + 10, 0);
        emon.Port.cellsSet(rtp, Retarget.rtpCell0() + 11, second);
        emon.Testport.assertEq(Retarget.rtLineState(oruns, olines, owords, rtp, scr, 0, 0, -1, 0, 1), 4, "the cells read what the line did, and surer: the line is replaced by them");
        emon.Port.cellsSet(rtp, Retarget.rtpCell0() + 5, -1);
        emon.Testport.assertEq(Retarget.rtLineState(oruns, olines, owords, rtp, scr, 0, 0, -1, 0, 1), 0, "a cell that was not read keeps the line");
    }
    public static void testAShareOfABigPageIsCountedIn64Bits() {
        // D1341: 3 000 000 painted pixels of a 2550 x 3300 page: 3 000 000 * 1000 is past 2^31, an overflow panic on Rust and a wrapped (negative) share on the others
        emon.Testport.assertEq(Retarget.rtPermille(3000000, (2550 * 3300) + 1), 356, "a share of 8 415 001 pixels");
        emon.Testport.assertEq(Retarget.rtPermille(1, 2), 500, "and a small one is as it was");
        emon.Testport.assertEq(Retarget.rtPermille(0, 5), 0, "and none is none");
    }
    public static void testABodyInkRunOfMoreLinesThanTheScratchHoldsIsCutNotReadPastIt() {
        // D1340: the per-line regions of `scr` are `sc-sel-max` (1500) cells each and the last ends the scratch; a body-ink run of 1600 lines wrote its flag for line 1500 past the end
        emon.Port.Cells oruns = emon.Port.newCells();
        emon.Port.Cells olines = emon.Port.newCells();
        emon.Port.Cells owords = emon.Port.newCells();
        emon.Port.Cells feats = emon.Port.newCells();
        emon.Port.Cells rtp = emon.Port.newCells();
        emon.Port.Cells scr = emon.Port.newCells();
        int i = 0;
        Scan.scPrep(scr);
        rttLine(olines, owords, feats, 0, 900);
        int fr = rttRun(oruns, olines, owords, 0, 0);
        int l1 = Evidence.olCount(olines);
        int w1 = Evidence.owCount(owords);
        while (i < 1600) {
            rttLine(olines, owords, feats, i * 10, 900);
            i += 1;
        }
        int br = rttRun(oruns, olines, owords, l1, w1);
        Retarget.rtPrep(rtp);
        emon.Port.cellsSet(rtp, Retarget.rtpBrun(), br);
        emon.Testport.assertEq(Retarget.rtCap(1600), Scan.scSelMax(), "a count over the region is the region's");
        emon.Testport.assertEq(Retarget.rtCap(7), 7, "and one under it is its own");
        int n = Retarget.rtAdopt(rtp, oruns, fr, olines, owords, scr);
        emon.Testport.assertThat(n <= Scan.scSelMax(), "the selection holds no more than the scratch has room for");
        emon.Testport.assertThat(n > 1400, "and the 1500 lines it counts are read, bar the few that lie over the first pass's line");
    }
